window.VN_LEARNING=window.VN_LEARNING||{};
window.VN_LEARNING["lesson-6"]={
  version:2,title:"Vitamins",chapter:6,duration:"105–125 minutes",
  outcomes:["Distinguish reliable vitamin sources from foods that only contain inactive analogues.","Explain why vitamin B12 requires a deliberate plan in vegan diets.","Connect vitamin D status with latitude, skin pigmentation, season, fortification and individual exposure.","Recognize why folate can correct anemia while allowing B12-related neurologic injury to progress.","Differentiate preformed vitamin A from provitamin A carotenoids and explain why conversion and dietary fat matter.","Use assessment, labels and referral rather than making blanket supplement recommendations."],
  modules:[
    {id:"vitamin-map",title:"Map the vitamin problem",summary:"Separate requirement, food source, absorption, conversion and storage before deciding that a diet is adequate.",moments:[
      {id:"l6-m1",title:"Adequacy is a pathway, not a food list",highYield:"A vegetarian diet can meet vitamin needs, but adequacy depends on reliable sources, amounts, bioavailability, life stage and consistency.",teaching:["Vitamins are organic compounds required in small amounts for metabolism, cell division, blood formation, nervous-system function, antioxidant systems and tissue maintenance. A plant-rich pattern supplies many vitamins generously, especially folate, vitamin C, carotenoids and vitamin K, but the word vegetarian does not guarantee adequacy. A diet can exclude meat while remaining low in produce, fortified foods or total energy.","For each vitamin, trace five questions: Is the nutrient present? Is the form biologically active? Is the amount sufficient? Can the person absorb or convert it? Is intake consistent enough for the body's storage pattern? This framework prevents confident claims based on one food or one day of intake."],keyPoints:["Diet label does not prove nutrient adequacy.","Food presence and usable form are different questions.","Absorption and conversion vary among people.","Life stage and consistency change risk."],visual:{title:"Vitamin adequacy pathway",kind:"flow",items:[{label:"Present",detail:"Food or supplement contains the nutrient"},{label:"Active",detail:"The form is biologically usable"},{label:"Enough",detail:"Amount and frequency meet need"},{label:"Absorbed",detail:"GI and medication factors allow uptake"},{label:"Used",detail:"Conversion, transport and tissue demand are supported"}]},mnemonic:{title:"P-A-E-A-U",cue:"Present · Active · Enough · Absorbed · Used",explanation:"Walk through the whole pathway before calling a source reliable."},goodToKnow:"A label can confirm fortification, but it cannot prove a person's status; biomarkers and clinical context may still be needed.",practiceConnection:"Ask which foods are actually eaten, how often, and whether products are fortified in the client's country. Do not infer adequacy from the word vegan or vegetarian.",activity:{prompt:"Which statement best evaluates vitamin adequacy?",options:[{text:"Confirm the source, active form, amount, absorption context and consistency",correct:true,feedback:"Correct. Adequacy depends on the full pathway."},{text:"Assume any plant-based diet supplies every vitamin automatically",correct:false,feedback:"Diet identity alone does not establish intake or bioavailability."},{text:"Count only the number of supplements used",correct:false,feedback:"Supplements can be absent, unnecessary, poorly dosed or poorly absorbed."}]}} ,
      {id:"l6-m2",title:"Storage changes how quickly a gap becomes visible",highYield:"Water-soluble does not mean harmless or never stored, and fat-soluble does not mean that high doses are safe.",teaching:["Vitamins A, D, E and K are classed as fat-soluble. They are absorbed with dietary lipid and can be stored to varying degrees. Most B vitamins and vitamin C are water-soluble, yet their handling is not identical: vitamin B12 can be stored for years, while thiamin reserves are limited. Classification helps predict absorption and storage but does not replace vitamin-specific knowledge.","Deficiency speed reflects body stores, growth, pregnancy, illness, intake and absorption. Infants can develop serious B12 deficiency much faster than an adult with established stores. Conversely, very high supplemental doses of some vitamins can cause harm even when the vitamin is water-soluble. Food-first teaching and dose-aware supplement review belong together."],keyPoints:["A, D, E and K are fat-soluble.","Most B vitamins and C are water-soluble.","B12 is water-soluble but substantially stored.","Supplement safety is dose-specific."],visual:{title:"Storage and urgency",kind:"comparison",items:[{label:"Limited reserve",detail:"Thiamin and vitamin C gaps may emerge relatively quickly"},{label:"Large reserve",detail:"B12 deficiency can be delayed in adults but rapid in infants"},{label:"Fat-soluble",detail:"Absorption needs fat; excess can accumulate"},{label:"High demand",detail:"Growth and pregnancy reduce the margin for error"}]},mnemonic:{title:"ADEK rides with fat",cue:"A · D · E · K",explanation:"Use the cue for absorption class, then learn each vitamin separately."},goodToKnow:"The onset of deficiency is not a stopwatch; previous intake and individual physiology matter.",practiceConnection:"When reviewing a supplement, record the exact nutrient form, dose, frequency and duration rather than writing only 'multivitamin.'",activity:{prompt:"Which water-soluble vitamin can be stored in substantial amounts?",options:[{text:"Vitamin B12",correct:true,feedback:"Correct. Adult liver stores can delay deficiency, although infants have much smaller reserves."},{text:"Vitamin C only",correct:false,feedback:"Vitamin C reserves are comparatively limited."},{text:"None of them",correct:false,feedback:"Water solubility does not mean zero storage."}]}}
    ]},
    {id:"b12",title:"Build a reliable B12 plan",summary:"Use fortified foods or supplements, understand absorption and recognize the urgency of deficiency.",moments:[
      {id:"l6-m3",title:"Reliable B12 is deliberate",highYield:"Unfortified plant foods are not dependable vitamin B12 sources; vegans need fortified foods and/or a supplement.",teaching:["Vitamin B12 is produced by microorganisms, not by plants or animals themselves. In modern food systems, dependable dietary B12 is found mainly in animal-derived foods and products deliberately fortified with B12. Nutritional yeast provides B12 only when the label confirms fortification. Spirulina, many seaweeds, fermented foods and unfortified yeast should not be presented as reliable sources.","Some foods contain B12-like compounds called analogues that are not active human B12. Older claims that poorly washed produce provides adequate B12 are unsafe: contamination is unpredictable and sanitation is protective. A reliable plan identifies a labelled fortified food or supplement, its dose and how consistently it is used."],keyPoints:["B12 is microbial in origin.","Fortification must be confirmed on the label.","Analogues are not dependable active B12.","Vegans require a planned reliable source."],visual:{title:"B12 source reliability",kind:"comparison",items:[{label:"Reliable",detail:"Measured supplement or labelled fortified food"},{label:"Potentially present",detail:"Dairy and eggs for lacto-ovo vegetarians, amounts vary"},{label:"Unreliable",detail:"Spirulina, unfortified yeast, fermented foods and unverified seaweed"},{label:"Unsafe assumption",detail:"Soil contamination or poor washing as a strategy"}]},mnemonic:{title:"F or S",cue:"Fortified food or Supplement",explanation:"If a vegan source is neither measured nor fortified, do not count it as the B12 plan."},goodToKnow:"The word nutritional yeast describes a product category, not a guarantee of B12 fortification.",practiceConnection:"Have the client bring the package or a photo of the Nutrition Facts panel. Product names and formulations change.",activity:{prompt:"Which is a dependable vegan B12 source?",options:[{text:"A product whose label confirms B12 fortification",correct:true,feedback:"Correct. The label establishes that active B12 was added."},{text:"Any seaweed",correct:false,feedback:"Seaweeds are not reliably dosed sources and may contain inactive analogues."},{text:"Unwashed garden vegetables",correct:false,feedback:"Contamination is unpredictable and not a safe nutrition strategy."}]}} ,
      {id:"l6-m4",title:"B12 supports blood, nerves and one-carbon metabolism",highYield:"Folate may improve the blood picture of B12 deficiency while neurologic damage continues, so folate is not a substitute.",teaching:["B12 is required for normal red-blood-cell development, neurologic integrity and reactions that process homocysteine and methyl groups. Deficiency can produce macrocytic anemia, fatigue, glossitis, numbness, gait changes, cognitive symptoms or developmental regression. Neurologic injury can become permanent when deficiency is prolonged.","Absorption from ordinary food doses requires stomach acid to release B12, binding proteins, pancreatic function, intrinsic factor and an intact terminal ileum. Large oral supplement doses can also provide a small amount by passive diffusion, but dosing and diagnosis belong with qualified care. Serum B12 is commonly measured; methylmalonic acid can help clarify borderline results."],keyPoints:["B12 supports red cells and nervous tissue.","Intrinsic factor and ileal function support absorption.","Folate does not prevent B12 neurologic injury.","Methylmalonic acid can clarify uncertain status."],visual:{title:"B12 route",kind:"sequence",items:[{label:"Release",detail:"Food B12 is freed in the stomach"},{label:"Bind",detail:"B12 joins intrinsic factor"},{label:"Absorb",detail:"Complex is taken up in the terminal ileum"},{label:"Transport",detail:"B12 circulates to tissues and storage"},{label:"Monitor",detail:"Symptoms and biomarkers guide assessment"}]},mnemonic:{title:"B12: Blood + Brain",cue:"Red cells · nerves · methyl transfer",explanation:"Remember that a normal-looking blood count does not rule out neurologic risk."},goodToKnow:"High folic-acid intake can correct megaloblastic anemia without correcting the underlying B12 problem.",practiceConnection:"Neurologic symptoms, severe fatigue, infant developmental concerns or suspected malabsorption require prompt medical assessment rather than a casual supplement suggestion.",activity:{prompt:"Why is folic acid not an adequate substitute for B12?",options:[{text:"It may improve anemia while B12-related neurologic injury continues",correct:true,feedback:"Correct. The blood picture can improve without correcting the nerve risk."},{text:"Folate destroys every B12 molecule",correct:false,feedback:"That is not the mechanism."},{text:"Folate and B12 have identical functions",correct:false,feedback:"Their pathways overlap, but they are not interchangeable."}]}}
    ]},
    {id:"vitamin-d",title:"Interpret vitamin D in context",summary:"Connect skin synthesis, season, latitude, pigmentation, fortified foods, supplements and clinical assessment.",moments:[
      {id:"l6-m5",title:"Sunlight is variable, not a prescription",highYield:"UVB-driven skin synthesis changes with season, latitude, time, clothing, skin pigmentation, age and sun-protection practices.",teaching:["Vitamin D can be synthesized in skin when ultraviolet B radiation reaches 7-dehydrocholesterol. The opportunity is not constant: winter at higher latitudes, indoor living, covering clothing, darker skin pigmentation, older age and several environmental factors can reduce production. This does not justify intentional sunburn or a universal number of minutes outdoors.","Public-health sun-safety guidance and vitamin D planning must coexist. Fortified foods and measured supplements provide more predictable intake than sunlight. Vegetarian-compatible D2 is widely available; D3 may be animal-derived or lichen-derived, so source and label matter when vegan suitability is important."],keyPoints:["UVB opportunity changes by season and latitude.","More melanin generally reduces synthesis from the same exposure.","Sunburn is not a vitamin strategy.","Fortified foods and supplements are predictable sources."],visual:{title:"Vitamin D context wheel",kind:"map",items:[{label:"Environment",detail:"Latitude, season, air and time of day"},{label:"Skin",detail:"Pigmentation, age and exposed area"},{label:"Behaviour",detail:"Indoor time, clothing and sunscreen"},{label:"Diet",detail:"Fortified foods and supplement use"},{label:"Health",detail:"Absorption, liver/kidney function and medicines"}]},mnemonic:{title:"LESS-D",cue:"Latitude · Exposure · Season · Skin · Diet",explanation:"Use the five factors before estimating risk."},goodToKnow:"Glass blocks much of the UVB needed for vitamin D synthesis, so sunlight through a window is not equivalent to outdoor exposure.",practiceConnection:"Use local public-health guidance and product labels. Do not prescribe unsafe UV exposure to correct suspected deficiency.",activity:{prompt:"Which factor can reduce vitamin D synthesis from the same UVB exposure?",options:[{text:"Greater skin pigmentation",correct:true,feedback:"Correct. More melanin generally lowers synthesis for a given exposure."},{text:"Eating vitamin C",correct:false,feedback:"Vitamin C intake does not block skin synthesis."},{text:"Chewing food longer",correct:false,feedback:"Chewing is unrelated to cutaneous vitamin D production."}]}} ,
      {id:"l6-m6",title:"Vitamin D status cannot be inferred from diet alone",highYield:"Vitamin D intake, skin synthesis, absorption and metabolism all contribute; measured status may be needed when risk is high.",teaching:["Vitamin D supports calcium and phosphate homeostasis, bone mineralization and other cellular functions. Deficiency in children can cause rickets; in adults it can contribute to osteomalacia. Supplements can prevent and treat deficiency when appropriately selected, so the old claim that supplemental vitamin D is inherently less effective than 'natural' vitamin D is misleading.","Fortification differs by country and product. A plant beverage may be fortified with vitamin D and calcium, or with neither. The name soy, oat or almond does not establish its nutrient profile. Clinical assessment considers intake, exposure, health conditions and, when indicated, serum 25-hydroxyvitamin D."],keyPoints:["Vitamin D supports mineral homeostasis and bone.","Supplemental vitamin D can be effective.","Fortification varies by brand and jurisdiction.","25-hydroxyvitamin D is the usual status marker."],visual:{title:"From source to bone",kind:"flow",items:[{label:"Input",detail:"Skin synthesis, fortified food or supplement"},{label:"Absorb",detail:"Dietary D enters with fat"},{label:"Activate",detail:"Liver and kidney form active metabolites"},{label:"Regulate",detail:"Calcium and phosphate handling"},{label:"Outcome",detail:"Bone mineralization and broader signalling"}]},mnemonic:{title:"25 first",cue:"25-hydroxyvitamin D = status marker",explanation:"Do not confuse the usual status test with the tightly regulated active hormone."},goodToKnow:"The active vitamin D metabolite can be normal despite low body stores; test interpretation belongs in clinical context.",practiceConnection:"Check the Nutrition Facts panel and serving size for fortified foods; avoid assuming all plant milks are equivalent.",activity:{prompt:"Which measure is commonly used to assess vitamin D status?",options:[{text:"Serum 25-hydroxyvitamin D",correct:true,feedback:"Correct. It reflects major inputs and stores better than the active hormone."},{text:"Serum vitamin C",correct:false,feedback:"That is a different vitamin."},{text:"Urinary protein alone",correct:false,feedback:"It does not establish vitamin D status."}]}}
    ]},
    {id:"other-vitamins",title:"Keep the rest of the vitamin picture connected",summary:"Use folate, thiamin and a varied food pattern without letting one abundant vitamin hide another gap.",moments:[
      {id:"l6-m7",title:"Folate and B12 share a pathway but not a job description",highYield:"High folate intake does not protect a person from B12-related nerve damage.",teaching:["Folate supports one-carbon metabolism, DNA synthesis and cell division. Legumes, leafy vegetables, citrus and fortified grain products can make folate intake strong in plant-rich diets. Before and during early pregnancy, folic-acid guidance is specific because adequate intake reduces neural-tube-defect risk; local prenatal recommendations should be followed.","Folate and B12 interact in methionine and nucleotide metabolism, which is why deficiency in either can cause macrocytic anemia. Yet only replacing folate can normalize red-cell production while B12-dependent neurologic processes remain impaired. Teach these nutrients together but never as substitutes."],keyPoints:["Folate supports DNA synthesis and cell division.","Plant-rich diets often provide food folate.","Periconception folic acid follows local guidance.","Folate cannot replace B12."],visual:{title:"Shared pathway, different safeguards",kind:"comparison",items:[{label:"Folate",detail:"One-carbon units and nucleotide synthesis"},{label:"B12",detail:"Methionine cycle, methylmalonyl-CoA pathway and nerves"},{label:"Shared sign",detail:"Macrocytic anemia can occur with either deficiency"},{label:"Critical difference",detail:"Neurologic B12 injury may continue after folate correction"}]},mnemonic:{title:"Folate fixes cells; B12 also guards cables",cue:"Division + nerves",explanation:"The 'cables' are a cue for neurologic tissue, not a literal mechanism."},goodToKnow:"Fortified grain products contain folic acid, while vegetables and legumes provide natural food folate forms.",practiceConnection:"Preconception counselling should verify both folic-acid planning and a reliable B12 source, especially in vegan patterns.",activity:{prompt:"Which statement is accurate?",options:[{text:"Folate can improve anemia without correcting B12-related neurologic risk",correct:true,feedback:"Correct. This is why B12 assessment cannot be replaced by folate."},{text:"Folate eliminates the need for B12",correct:false,feedback:"The nutrients are not interchangeable."},{text:"Leafy greens are a dependable source of active B12",correct:false,feedback:"They provide folate, not reliable B12."}]}} ,
      {id:"l6-m8",title:"Thiamin and other vitamins reward variety",highYield:"Whole and enriched grains, legumes, seeds, nuts, vegetables and fruit create overlapping vitamin coverage; extreme restriction removes that redundancy.",teaching:["Thiamin is a coenzyme in carbohydrate and branched-chain amino-acid metabolism. Whole and enriched grains, legumes, nuts and seeds contribute it. Certain raw-food enzymes or compounds can degrade thiamin in unusual contexts, but ordinary varied vegetarian eating is not defined by the broad list of foods in an old true-or-false item. Dose, preparation and overall pattern matter.","Riboflavin, niacin, vitamin B6, vitamin C, vitamin E, vitamin K and provitamin A carotenoids each have distinct roles and sources. The practical strategy is not to memorize one superfood per vitamin. Build repeated coverage across legumes or soy foods, whole or enriched grains, vegetables, fruit, nuts/seeds and reliably fortified foods."],keyPoints:["Thiamin supports energy metabolism.","Variety creates nutrient redundancy.","Extreme restriction narrows coverage.","One food rarely determines vitamin status."],visual:{title:"Overlapping vitamin coverage",kind:"map",items:[{label:"Legumes and soy",detail:"Folate, thiamin, B6 and other micronutrients"},{label:"Whole/enriched grains",detail:"Thiamin, niacin, riboflavin and folate"},{label:"Vegetables and fruit",detail:"Vitamin C, folate, carotenoids and K"},{label:"Nuts and seeds",detail:"Vitamin E, thiamin and healthy fats"},{label:"Fortified foods",detail:"Strategic B12, D and other additions"}]},mnemonic:{title:"LGVNF",cue:"Legumes · Grains · Vegetables/fruit · Nuts/seeds · Fortified",explanation:"Use the five groups to check breadth, not as a rigid food guide."},goodToKnow:"Cooking losses, storage and processing affect some vitamins more than others, but adequacy is judged across the full diet.",practiceConnection:"When a client reports a long elimination list, map which food groups disappeared and which vitamins lost their repeated sources.",activity:{prompt:"What is the strongest general strategy for broad vitamin coverage?",options:[{text:"A varied pattern plus deliberate fortified sources where needed",correct:true,feedback:"Correct. Variety provides overlap while fortification addresses predictable gaps."},{text:"One large dose of every vitamin regardless of need",correct:false,feedback:"High doses can be unnecessary or harmful."},{text:"Rely on one raw food for all vitamins",correct:false,feedback:"No single food reliably covers every vitamin."}]}} ,
      {id:"l6-m9",title:"Carotenoids are raw material, not preformed vitamin A",highYield:"Orange and dark-green plants provide provitamin A carotenoids that the intestine must convert; retinol activity equivalents account for the lower, variable conversion.",teaching:["Vitamin A supports vision, epithelial integrity, immunity, reproduction and development. Animal-derived foods and some supplements contain preformed vitamin A as retinol or retinyl esters. Plants supply provitamin A carotenoids such as beta-carotene, alpha-carotene and beta-cryptoxanthin. Lutein, zeaxanthin and lycopene are useful carotenoids but are not converted to vitamin A.","Conversion is not one-to-one. Retinol activity equivalent units reflect the lower bioactivity of food carotenoids, and conversion varies with the food matrix, fat in the meal, nutrient status and genetics. Chopping and cooking can release carotenoids from plant tissue, while a modest amount of dietary fat supports micelle formation and absorption. Repeated servings of orange and dark-green produce are more dependable than one occasional superfood."],keyPoints:["Preformed retinol and provitamin A carotenoids are different inputs.","Not every carotenoid becomes vitamin A.","Food beta-carotene has lower and variable conversion.","Food preparation and dietary fat can support absorption."],visual:{title:"Two routes to usable vitamin A",kind:"comparison",items:[{label:"Preformed route",detail:"Retinol or retinyl esters are already vitamin A"},{label:"Plant route",detail:"Provitamin A carotenoids require intestinal conversion"},{label:"Absorption help",detail:"Chopping/cooking plus a meal containing fat"},{label:"Planning result",detail:"Repeat orange and dark-green produce across the week"}]},mnemonic:{title:"A from colour needs conversion",cue:"Carotenoid → convert → retinoid function",explanation:"The colour cue identifies candidates; it does not make every carotenoid vitamin A."},goodToKnow:"Carrots can supply beta-carotene, but the body does not absorb or convert every microgram into retinol. That is why vitamin A recommendations use retinol activity equivalents.",practiceConnection:"For a highly restrictive vegan pattern, ask about orange vegetables, dark leafy greens, meal fat and fat-malabsorption conditions rather than simply asking whether the client eats vegetables.",activity:{prompt:"Which statement correctly compares beta-carotene with retinol?",options:[{text:"Food beta-carotene is a provitamin that must be converted to vitamin A",correct:true,feedback:"Correct. Conversion is variable and less efficient than the use of preformed retinol."},{text:"Every carotenoid is converted completely to vitamin A",correct:false,feedback:"Many carotenoids are not provitamin A, and conversion is never complete."},{text:"Dietary fat prevents carotenoid absorption",correct:false,feedback:"A modest amount of fat generally supports carotenoid absorption."}]}} ,
      {id:"l6-m10",title:"Supplement form and dose change the safety question",highYield:"Food carotenoids, beta-carotene supplements and preformed retinol are not interchangeable; the upper limit applies to preformed vitamin A, which can accumulate and cause toxicity.",teaching:["Fat-soluble vitamin supplements can concentrate exposures far beyond food intake. Chronic excess preformed vitamin A can injure the liver and bone and is teratogenic in pregnancy. The tolerable upper intake level is therefore expressed for preformed retinol/retinyl esters, not for carotenoids naturally present in food. High-dose beta-carotene supplements are not a general wellness strategy either and have produced harm in some high-risk smoking populations.","Supplement review must identify the chemical form, amount per serving, number of servings, all duplicate products and relevant medicines. A multivitamin labelled simply 'vitamin A' may contain retinyl palmitate, beta-carotene or both. Pregnancy, liver disease, fat-malabsorption treatment and prescription retinoids change the safety conversation and call for qualified care."],keyPoints:["Preformed vitamin A can accumulate and cause toxicity.","Pregnancy makes retinoid dose review especially important.","A label must be read for form as well as amount.","Duplicate supplements can silently raise total exposure."],visual:{title:"Vitamin A label audit",kind:"sequence",items:[{label:"Form",detail:"Retinol/retinyl ester, beta-carotene or mixture"},{label:"Amount",detail:"Dose per serving in mcg RAE"},{label:"Frequency",detail:"How many servings and how often"},{label:"Duplicates",detail:"Prenatal, multivitamin and stand-alone products"},{label:"Context",detail:"Pregnancy, liver health, smoking and medicines"}]},mnemonic:{title:"F-A-D-C",cue:"Form · Amount · Duplicates · Context",explanation:"Use the four checks before interpreting a vitamin A supplement."},goodToKnow:"A product can supply the same labelled vitamin in biologically and toxicologically different forms.",practiceConnection:"Do not recommend a high-dose vitamin A product in pregnancy or alongside prescription retinoids; review the exact label with the prenatal or medical team.",activity:{prompt:"Which exposure is counted toward the adult upper limit for vitamin A?",options:[{text:"Preformed vitamin A from retinol or retinyl esters",correct:true,feedback:"Correct. The UL is based on preformed vitamin A because it can accumulate and cause toxicity."},{text:"Beta-carotene naturally present in carrots",correct:false,feedback:"Food carotenoids are not counted toward the preformed-vitamin-A UL."},{text:"Every green pigment in vegetables",correct:false,feedback:"Plant pigments are not all vitamin A or provitamin A."}]}}
    ]}
  ],
  caseStudy:{title:"A vegan diet with no verified B12 source",scenario:"A 29-year-old vegan eats many vegetables, legumes and whole grains but does not use supplements. They assume spirulina and unfortified nutritional yeast provide B12. They report new tingling and fatigue.",prompts:["Which claim in the current plan is unsafe?","Which symptoms make prompt clinical assessment important?","What product information would you verify?","How would you explain folate's inability to substitute for B12?"],takeaway:"A nutrient-dense vegan pattern can still have a predictable B12 gap. Verify a reliable source and escalate neurologic symptoms rather than relying on food folklore."},
  recap:["Vitamin adequacy depends on source, form, amount, absorption and consistency.","Vegans need a reliable B12 source from fortified foods and/or supplements.","B12 supports red cells, nerves and one-carbon metabolism.","Folate can improve anemia without stopping B12 neurologic injury.","Vitamin D synthesis changes with season, latitude, pigmentation and behaviour.","Fortification varies; labels matter.","Plant carotenoids require conversion to vitamin A, and not every carotenoid is provitamin A.","Preformed retinol, beta-carotene and food carotenoids have different safety profiles.","Variety provides overlapping coverage, while supplementation should be dose-aware and assessed."],
  flashcards:[{front:"Reliable vegan B12 sources",back:"Measured supplements and foods whose labels confirm B12 fortification.",tag:"B12"},{front:"B12 analogue",back:"A B12-like compound that may not function as active human B12 and should not be counted as a reliable source.",tag:"B12"},{front:"Intrinsic factor",back:"A gastric protein required for receptor-mediated B12 absorption in the terminal ileum.",tag:"B12"},{front:"Methylmalonic acid",back:"A functional marker that can rise in B12 deficiency and help clarify borderline serum B12.",tag:"B12"},{front:"Folate masking",back:"Folate may correct macrocytic anemia while B12-related neurologic injury continues.",tag:"folate"},{front:"25-hydroxyvitamin D",back:"The blood measure commonly used to assess vitamin D status.",tag:"vitamin D"},{front:"Vitamin D variables",back:"Latitude, season, pigmentation, age, exposure, diet, absorption and metabolism.",tag:"vitamin D"},{front:"Fat-soluble vitamins",back:"Vitamins A, D, E and K.",tag:"classification"},{front:"Thiamin",back:"A B vitamin important in carbohydrate and branched-chain amino-acid metabolism.",tag:"B vitamins"},{front:"Fortified food",back:"A food to which nutrients were deliberately added; the label and serving size establish the amount.",tag:"planning"},{front:"Vitamin adequacy",back:"A match among reliable intake, usable form, absorption, need and consistency.",tag:"planning"},{front:"High-risk B12 symptom",back:"Neurologic change such as tingling, gait difficulty, cognitive change or infant developmental regression requires prompt assessment.",tag:"safety"},{front:"Provitamin A carotenoid",back:"A plant pigment such as beta-carotene that can be converted to vitamin A; conversion is incomplete and variable.",tag:"vitamin A"},{front:"Non-provitamin A carotenoid",back:"A carotenoid such as lutein, zeaxanthin or lycopene that is not converted into vitamin A.",tag:"vitamin A"},{front:"Vitamin A supplement audit",back:"Check form, amount, frequency, duplicates and clinical context.",tag:"safety"}],
  practice:[{prompt:"Name two dependable vegan B12 strategies.",answer:"A measured B12 supplement and/or regularly eaten foods whose labels confirm B12 fortification.",rationale:"Unfortified plant foods and analogues are unreliable.",tag:"B12"},{prompt:"Why is spirulina not counted as a dependable B12 source?",answer:"It can contain inactive B12-like analogues and its usable B12 content is not reliable.",rationale:"Source reliability requires active form and measured amount.",tag:"B12"},{prompt:"What protein enables receptor-mediated B12 absorption?",answer:"Intrinsic factor.",rationale:"The intrinsic-factor–B12 complex is absorbed in the terminal ileum.",tag:"B12"},{prompt:"Why can folate make B12 deficiency harder to notice?",answer:"It may improve macrocytic anemia while neurologic injury continues.",rationale:"The nutrients overlap in blood-cell pathways but are not interchangeable.",tag:"folate"},{prompt:"List four factors that affect cutaneous vitamin D synthesis.",answer:"Examples include latitude, season, time of day, pigmentation, age, clothing and exposed skin area.",rationale:"Sunlight opportunity is highly variable.",tag:"vitamin D"},{prompt:"Which test is commonly used for vitamin D status?",answer:"Serum 25-hydroxyvitamin D.",rationale:"It reflects major inputs and stores better than the active hormone.",tag:"vitamin D"},{prompt:"What does ADEK stand for?",answer:"Vitamins A, D, E and K, the fat-soluble vitamins.",rationale:"The classification helps organize absorption and storage.",tag:"classification"},{prompt:"Why should a plant beverage label be checked?",answer:"Vitamin D, calcium, B12, protein and serving sizes vary by brand and jurisdiction.",rationale:"The product name does not establish fortification.",tag:"labels"},{prompt:"What makes infants especially vulnerable to B12 deficiency?",answer:"Small stores, rapid growth and dependence on maternal milk or formula sources.",rationale:"Neurologic injury can develop quickly.",tag:"life stage"},{prompt:"Give the five-part vitamin adequacy pathway.",answer:"Present, active, enough, absorbed and used.",rationale:"The pathway prevents food-list assumptions.",tag:"planning"},{prompt:"Why does beta-carotene not equal the same amount of retinol?",answer:"Food beta-carotene must be absorbed and converted, and both processes are incomplete and variable.",rationale:"Retinol activity equivalent units account for different bioactivity.",tag:"vitamin A"},{prompt:"Which vitamin A form drives the established upper limit?",answer:"Preformed vitamin A as retinol or retinyl esters.",rationale:"These forms can accumulate and produce liver, bone and pregnancy-related toxicity.",tag:"safety"}],
  sources:[{title:"NIH ODS · Vitamin A and Carotenoids",url:"https://ods.od.nih.gov/factsheets/VitaminA-HealthProfessional/"},{title:"NIH ODS · Vitamin B12",url:"https://ods.od.nih.gov/factsheets/VitaminB12-HealthProfessional/"},{title:"NIH ODS · Vitamin D",url:"https://ods.od.nih.gov/factsheets/VitaminD-HealthProfessional/"},{title:"NIH ODS · Folate",url:"https://ods.od.nih.gov/factsheets/Folate-HealthProfessional/"}]
};
